import React from 'react';
import '../../../styles/GlobalStyles.css';

const AttendeeDashboard = () => {
  // Dummy data for demonstration
  const myEvents = [
    { id: 1, title: 'Tech Conference 2025', date: '2025-05-01', ticket: 'VIP' },
    { id: 2, title: 'Startup Pitch Session', date: '2025-06-15', ticket: 'General' },
  ];

  return (
    <div className="container">
      <div className="card">
        <h2>Attendee Dashboard</h2>
        <p>View your registered events, access live sessions, and more.</p>
        
        {/* Personalized Schedule Section */}
        <section>
          <h3>Personalized Schedule</h3>
          <ul>
            {myEvents.map(event => (
              <li key={event.id} style={{ marginBottom: '0.5rem' }}>
                <strong>{event.title}</strong> | Date: {event.date} | Ticket: {event.ticket}
              </li>
            ))}
          </ul>
        </section>
        
        {/* Engagement Tools Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Engagement Tools</h3>
          <button className="btn" style={{ marginRight: '1rem' }}>Join Live Chat</button>
          <button className="btn">Participate in Q&amp;A</button>
        </section>
        
        {/* Feedback & Support Section */}
        <section style={{ marginTop: '2rem' }}>
          <h3>Feedback &amp; Support</h3>
          <p>If you have any issues, please send us your feedback.</p>
          <input 
            type="text" 
            placeholder="Type your feedback here..." 
            style={{ 
              width: '100%', 
              padding: '0.5rem', 
              borderRadius: '4px', 
              border: '1px solid #444', 
              backgroundColor: '#1e1e1e', 
              color: '#e0e0e0' 
            }}
          />
          <button className="btn" style={{ marginTop: '1rem' }}>Submit Feedback</button>
        </section>
      </div>
    </div>
  );
};

export default AttendeeDashboard;
